from __future__ import annotations

from fastapi.responses import HTMLResponse

from app.build_info import APP_VERSION, BUILD_ID


def hunting_page() -> HTMLResponse:
    html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Hunt Services</title>
<style>
:root{color-scheme:dark;--bg:#08131b;--panel:#101d26;--line:#294553;--text:#edf6fb;--muted:#9eb0b8;--accent:#57d6bf;--blue:#73bfff;--good:#61d095;--warn:#f4c95d;--bad:#ff7b7b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#102b35,#08131b 48%);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}header,main{max-width:1220px;margin:auto}header{position:sticky;top:0;z-index:100;padding:16px 0 14px;border-bottom:1px solid var(--line);background:rgba(8,19,27,.97);backdrop-filter:blur(14px)}h1{margin:0 0 4px;font-size:26px}h2{margin:0 0 8px;font-size:19px}h3{margin:17px 0 8px;font-size:15px}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.sub,.hint,.meta,.empty{color:var(--muted)}.sub{margin:0}.nav,.analysis-tabs,.actions,.source-links,.chips{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.nav{margin-top:12px}.nav a,.analysis-tabs a,.source-links a{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:9px 13px;text-decoration:none;font-weight:700}.nav a.active,.analysis-tabs a.active{background:var(--accent);border-color:var(--accent);color:#07171b}main{padding:24px 0 60px}.analysis-tabs{margin-bottom:16px}.analysis-tabs a{padding:7px 11px}.panel{background:rgba(16,29,38,.96);border:1px solid var(--line);border-radius:12px;padding:18px;margin-bottom:18px;box-shadow:0 10px 35px #0003}.picker{display:grid;grid-template-columns:1.5fr 1.5fr auto auto;gap:10px;align-items:end}.filters{display:grid;grid-template-columns:2fr repeat(3,1fr) auto;gap:10px;align-items:end;margin:14px 0}.checkbox{display:flex;align-items:center;gap:7px;min-height:42px}.checkbox input{width:auto}label{display:block;color:#bed0da;font-size:12px;font-weight:700;margin:4px 0 5px}select,input{width:100%;background:#0b1520;color:var(--text);border:1px solid #365268;border-radius:8px;padding:10px 11px;font:inherit}button{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:10px 14px;font:inherit;font-weight:750;cursor:pointer}button.secondary{background:transparent;border-color:#49617d}button:disabled{opacity:.5;cursor:not-allowed}.status{min-height:22px;margin-top:10px;color:var(--muted)}.status.good{color:var(--good)}.status.warn{color:var(--warn)}.status.bad{color:var(--bad)}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin:13px 0}.card,.category-card,.change-card{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:10px}.card strong,.change-card strong{display:block;color:var(--blue);font-size:20px}.category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.category-card strong{display:block;font-size:17px;color:var(--accent)}.chip{display:inline-block;margin:2px 4px 2px 0;padding:3px 7px;border-radius:99px;background:#243f4d;font-size:11px}.chip.exposed{background:#34414a}.chip.inferred{background:#4a3d21;color:#ffe3a8}.chip.observed{background:#173f5c;color:#bce4ff}.chip.correlated{background:#174b3c;color:#bdf4dc}.chip.nonstandard{background:#512e54;color:#f1c8f3}.help{padding:11px 13px;border-left:4px solid var(--blue);background:#0a1720;border-radius:7px;margin:12px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:900px}th,td{text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid var(--line);font-size:12px}th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.04em}.host-row.hidden-row{display:none}.warning{padding:10px 12px;background:#2b2416;border:1px solid #8b692a;color:#ffe3a8;border-radius:8px;margin:8px 0}.changes{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 0}.change-list{display:grid;grid-template-columns:1fr 1fr;gap:12px}.change-list section{background:#0a1720;border:1px solid var(--line);border-radius:9px;padding:12px}.change-list ul{margin:8px 0;padding-left:18px}.hidden{display:none!important}.footer{color:var(--muted);font-size:12px}@media(max-width:1240px){header,main{padding-left:4vw;padding-right:4vw}}@media(max-width:900px){.picker,.filters,.change-list{grid-template-columns:1fr}.cards,.category-grid,.changes{grid-template-columns:1fr 1fr}}
</style></head><body>
<header><div class="eyebrow">Dedicated hunting view</div><h1>Hunt Services</h1><p class="sub">Turn retained Nmap evidence into service-aware capability leads without executing anything.</p><nav class="nav" aria-label="Primary"><a href="/scans">Nmap Scans</a><a class="active" href="/analysis" aria-current="page">Analyze Results</a><a href="/device-config">Device Configurations</a><a href="/network-map">Network Map</a></nav></header>
<main><nav class="analysis-tabs" aria-label="Analysis views"><a href="/analysis">Nmap Results</a><a href="/device-analysis">Network Device Analysis</a><a class="active" href="/hunting" aria-current="page">Hunt Services</a></nav>
<section class="panel"><h2>Choose retained scan evidence</h2><p class="hint">Hunt one completed scan, or select an older scan as a comparison baseline.</p><div class="picker"><div><label for="currentRun">Scan to hunt</label><select id="currentRun"><option value="">Loading completed scans…</option></select></div><div><label for="baselineRun">Optional comparison baseline</label><select id="baselineRun"><option value="">No comparison</option></select></div><button id="hunt">Hunt</button><button id="compare" class="secondary" disabled>Compare</button></div><div id="status" class="status" role="status"></div></section>
<section id="huntPanel" class="hidden"><section class="panel"><div id="huntHeading"></div><div id="cards" class="cards"></div><div id="sources" class="source-links"></div><div id="warnings"></div></section><section class="panel"><h2>Capability categories</h2><div id="categories" class="category-grid"></div><div class="help"><strong>How the labels work</strong><br><span class="meta"><strong>Exposed</strong> means an open service is reachable. <strong>Inferred</strong> uses a conventional port. <strong>Observed</strong> uses the Nmap service fingerprint. <strong>Correlated</strong> means both signals agree.</span></div></section><section class="panel"><h2>Combined hunting filters</h2><div class="filters"><div><label for="search">Host, service, product, version, or port</label><input id="search" type="search" placeholder="Try SSH, 443, Windows, or a hostname"></div><div><label for="category">Category</label><select id="category"><option value="">All categories</option></select></div><div><label for="protocol">Protocol</label><select id="protocol"><option value="">All protocols</option><option value="tcp">TCP</option><option value="udp">UDP</option></select></div><div><label for="capability">Capability evidence</label><select id="capability"><option value="">All evidence levels</option><option value="exposed">Exposed</option><option value="inferred">Inferred</option><option value="observed">Observed</option><option value="correlated">Correlated</option></select></div><label class="checkbox"><input id="nonstandard" type="checkbox"> Nonstandard ports only</label></div><p id="visibleCount" class="meta"></p><div class="table-wrap"><table><thead><tr><th>Host</th><th>Category</th><th>Capability evidence</th><th>Port</th><th>Observed service</th><th>Match basis</th></tr></thead><tbody id="findingRows"></tbody></table></div></section></section>
<section id="comparisonPanel" class="panel hidden"><h2>Hunting changes</h2><div id="comparison"></div></section><div class="footer">Build <code>{APP_VERSION}</code> · <code>{BUILD_ID}</code></div></main>
<script>
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let candidates=[],current=null;
function setStatus(message,kind=''){$('status').textContent=message;$('status').className='status '+kind}
function when(value){if(!value)return'—';const parsed=new Date(value);return Number.isNaN(parsed.valueOf())?value:parsed.toLocaleString()}
function label(item){return item.comparison_name||`${item.display_name||'Scan'} · ${when(item.completed_at||item.created_at)}`}
function optionRows(items){return items.map(item=>`<option value="${esc(item.selection_run_id)}">${esc(label(item))}</option>`).join('')}
function refreshBaselines(){const id=$('currentRun').value;$('baselineRun').innerHTML='<option value="">No comparison</option>'+optionRows(candidates.filter(item=>item.selection_run_id!==id));$('compare').disabled=!id||!$('baselineRun').value}
function loadOptions(){const prior=$('currentRun').value,requested=new URLSearchParams(location.search).get('run');$('currentRun').innerHTML='<option value="">Choose a completed scan…</option>'+optionRows(candidates);const selected=requested||prior;if(candidates.some(item=>item.selection_run_id===selected))$('currentRun').value=selected;refreshBaselines();if(requested&&$('currentRun').value)hunt()}
function stateChips(item){return(item.evidence_states||[]).map(state=>`<span class="chip ${esc(state)}">${esc(state)}</span>`).join('')+(item.nonstandard_port?'<span class="chip nonstandard">nonstandard port</span>':'')}
function sourceLinks(source){return(source?.evidence?.sources||[]).map(item=>`<a href="${esc(item.url)}" target="_blank" rel="noopener">${esc(item.label)}</a>`).join('')}
function renderHunt(data){current=data;$('huntPanel').classList.remove('hidden');const source=data.source||{},states=data.capability_states||{};$('huntHeading').innerHTML=`<h2>${esc(source.display_name||'Service hunt')}</h2><p class="meta">${esc(source.comparison_name||when(source.completed_at||source.created_at))}</p>`;const cards=[['Hosts with findings',data.host_count],['Capability findings',data.finding_count],['Nonstandard ports',data.nonstandard_finding_count],['Observed fingerprints',states.observed],['Correlated findings',states.correlated]];$('cards').innerHTML=cards.map(([name,value])=>`<div class="card"><strong>${Number(value||0)}</strong>${esc(name)}</div>`).join('');$('sources').innerHTML=sourceLinks(source);$('warnings').innerHTML=(data.warnings||[]).map(item=>`<div class="warning">${esc(item)}</div>`).join('');$('categories').innerHTML=(data.categories||[]).map(item=>`<div class="category-card"><strong>${item.finding_count}</strong>${esc(item.name)}</div>`).join('')||'<p class="empty">No categorized open services were found.</p>';$('category').innerHTML='<option value="">All categories</option>'+(data.categories||[]).map(item=>`<option value="${esc(item.name)}">${esc(item.name)}</option>`).join('');$('findingRows').innerHTML=(data.findings||[]).map((item,index)=>{const search=[item.ip,item.hostname,item.os,item.os_group,item.category,item.protocol,item.port,item.service,item.product,item.version,...(item.match_basis||[])].join(' ').toLowerCase();return`<tr class="host-row" data-index="${index}" data-category="${esc(item.category)}" data-protocol="${esc(item.protocol)}" data-states="${esc((item.evidence_states||[]).join(' '))}" data-nonstandard="${item.nonstandard_port?'yes':'no'}" data-search="${esc(search)}"><td><strong>${esc(item.ip||item.hostname||'—')}</strong><br><span class="meta">${esc(item.hostname||item.os_group||'')}</span></td><td>${esc(item.category)}</td><td>${stateChips(item)}</td><td><code>${esc(item.port)}/${esc(item.protocol)}</code>${item.outlier?'<br><span class="chip inferred">outlier</span>':''}</td><td>${esc(item.service||'unknown')}<br><span class="meta">${esc([item.product,item.version].filter(Boolean).join(' ')||'No product fingerprint')}</span></td><td>${(item.match_basis||[]).map(esc).join('<br>')}</td></tr>`}).join('');applyFilters();$('huntPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function applyFilters(){if(!current)return;const term=$('search').value.trim().toLowerCase(),category=$('category').value,protocol=$('protocol').value,state=$('capability').value,nonstandard=$('nonstandard').checked;let visible=0;document.querySelectorAll('.host-row').forEach(row=>{const show=(!term||row.dataset.search.includes(term))&&(!category||row.dataset.category===category)&&(!protocol||row.dataset.protocol===protocol)&&(!state||row.dataset.states.split(' ').includes(state))&&(!nonstandard||row.dataset.nonstandard==='yes');row.classList.toggle('hidden-row',!show);if(show)visible++});$('visibleCount').textContent=`${visible} of ${current.finding_count||0} capability findings shown.`}
async function hunt(){const id=$('currentRun').value;if(!id){setStatus('Choose a completed scan first.','warn');return}setStatus('Building the service hunting view…');try{const response=await fetch(`/api/hunting/${encodeURIComponent(id)}`),data=await response.json();if(!response.ok)throw new Error(data.detail||'Hunting analysis failed');renderHunt(data);setStatus('Hunting analysis complete.','good')}catch(error){setStatus(error.message,'bad')}}
function findingText(item){return`${item.ip||item.hostname||'host'} · ${item.category} · ${item.port}/${item.protocol} ${item.service||''}`}
function list(title,items,render){return`<section><h3>${esc(title)} <span class="chip">${items.length}</span></h3>${items.length?`<ul>${items.map(item=>`<li>${esc(render(item))}</li>`).join('')}</ul>`:'<p class="empty">None</p>'}</section>`}
async function compare(){const before=$('baselineRun').value,after=$('currentRun').value;if(!before||!after)return;setStatus('Comparing hunting evidence…');try{const response=await fetch(`/api/hunting/compare?before=${encodeURIComponent(before)}&after=${encodeURIComponent(after)}`),data=await response.json();if(!response.ok)throw new Error(data.detail||'Hunting comparison failed');const s=data.summary||{};$('comparisonPanel').classList.remove('hidden');const coverage=(data.coverage_warnings||[]).map(item=>`<div class="warning">${esc(item)}</div>`).join('');$('comparison').innerHTML=`${coverage}<p class="meta">${esc(data.before?.comparison_name||'Baseline')} → ${esc(data.after?.comparison_name||'Current')}</p><div class="changes">${Object.entries(s).map(([name,value])=>`<div class="change-card"><strong>${value}</strong>${esc(name.replaceAll('_',' '))}</div>`).join('')}</div><div class="change-list">${list('Findings added',data.findings_added||[],findingText)}${list('Findings removed',data.findings_removed||[],findingText)}${list('Findings changed',data.findings_changed||[],item=>`${findingText(item.finding)} · ${Object.keys(item.changes).join(', ')}`)}${list('Host category changes',data.host_category_changes||[],item=>`${item.host_key} · added: ${item.categories_added.join(', ')||'—'} · removed: ${item.categories_removed.join(', ')||'—'}`)}</div>`;setStatus('Hunting comparison complete.','good');$('comparisonPanel').scrollIntoView({behavior:'smooth',block:'start'})}catch(error){setStatus(error.message,'bad')}}
async function loadCandidates(){try{const response=await fetch('/api/scan-comparisons/candidates'),data=await response.json();if(!response.ok)throw new Error(data.detail||'Completed scans unavailable');candidates=data;loadOptions();setStatus(`${candidates.length} completed scan${candidates.length===1?'':'s'} available.`,'good')}catch(error){setStatus(error.message,'bad')}}
$('currentRun').onchange=refreshBaselines;$('baselineRun').onchange=()=>{$('compare').disabled=!$('baselineRun').value||!$('currentRun').value};$('hunt').onclick=hunt;$('compare').onclick=compare;for(const id of['search','category','protocol','capability','nonstandard'])$(id).addEventListener(id==='search'?'input':'change',applyFilters);loadCandidates();
</script></body></html>'''
    return HTMLResponse(
        html.replace("{APP_VERSION}", APP_VERSION).replace("{BUILD_ID}", BUILD_ID)
    )
